import{_ as o,l as s,o as e,c as l,v as t,p as n,x as r,d as C,i as P,S as p}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"IPC 与利用率","description":"","frontmatter":{"title":"IPC 与利用率","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ipc-util.md","filePath":"cs/ipc-util.md","lastUpdated":1789023840000}'),c={name:"cs/ipc-util.md"};function d(I,a,h,m,E,u){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="ipc-与利用率" tabindex="-1">IPC 与利用率 <a class="header-anchor" href="#ipc-与利用率" aria-label="Permalink to &quot;IPC 与利用率&quot;">​</a></h1><div class="epigraph"><p>CPI 是每条指令多少拍；翻过来，IPC 是每拍提交几条。窗口、端口和停顿让这个数远小于发射宽度。</p><footer>—— 据 Hennessy and Patterson, Computer Architecture: A Quantitative Approach 整理</footer></div><p><a href="/cs/cpi-amdahl">上一课</a>把 CPU 时间写成指令数 × CPI × 周期，五级理想 CPI 为 1，停顿另加。本课不重推阿姆达尔公式。缺口是：一旦每拍可以完成不止一条（后课超标量），或反过来因停顿每拍完成不到一条，用「每拍指令数」看利用率更直接。本课只钉 IPC = 1/CPI（在单线程、按提交计时），以及利用率相对理想宽度的缺口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理想五级每拍提交 1 条，IPC = 1。load-use、误预测、结构冲突让 IPC \\(\\lt\\) 1，与 CPI &gt; 1 是同一件事的倒数。设计者若只报时钟频率，看不出流水线经常空转。缺口不是新的冒险类型，而是<strong>把吞吐写成 IPC，把空档写成利用率 = 实测 IPC / 理想宽度</strong>。</p><p>上一课声明不引入 IPC 大于 1。本课把符号准备好：理想宽度暂时仍是 1；后课把宽度改成 \\(W\\)，理想 IPC 上限变成 \\(W\\)，利用率是 \\(\\mathrm{IPC}/W\\)。</p><p><span class="marginnote">IPC 按提交计，不按投机执行计。冲刷掉的指令不进入分子，否则预测器会虚高。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在一段程序上计数：提交指令数 \\(N\\)，时钟数 \\(C\\)，则 \\(\\mathrm{IPC}=N/C\\)，\\(\\mathrm{CPI}=C/N\\)。停顿分类仍用上一课：结构、数据、控制、异常。利用率 \\(u=\\mathrm{IPC}/W\\)，\\(W=1\\) 时 \\(u=\\mathrm{IPC}\\)。</p>',9)),(e(),n(p,null,{default:r(()=>[P(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E6%8F%90%E4%BA%A4%E6%8C%87%E4%BB%A4%E6%95%B0%22%5D%20--%3E%20IPC%5B%22IPC%20%3D%20N%20%2F%20%E6%97%B6%E9%92%9F%22%5D%0A%20%20STALL%5B%22%E5%81%9C%E9%A1%BF%E6%8B%8D%22%5D%20--%3E%20IPC%0A%20%20IPC%20--%3E%20U%5B%22%E5%88%A9%E7%94%A8%E7%8E%87%20%3D%20IPC%20%2F%20%E5%AE%BD%E5%BA%A6%22%5D%0A%20%20U%20--%3E%20A%5B%22%E9%98%BF%E5%A7%86%E8%BE%BE%E5%B0%94%EF%BC%9A%E5%81%9C%E9%A1%BF%E9%A1%B9%E5%B0%81%E9%A1%B6%20IPC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[C(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>比较两种微结构时，同时看 IPC 与周期：转发 mux 可能降频率、升 IPC，净时间不一定赢。这与上一课「三项都要看」一致，只是把 CPI 换成它的倒数谈吞吐。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>流水线寄存器在飞、功能单元却等数据，就是利用率缺口。后课 cache 缺失把 MEM 级拉成许多拍，IPC 掉到接近 0 的区间，局部性课要解释为什么平均仍可救。本课只承认：IPC 对停顿过敏，对「指令算得更巧」不直接敏感——那是指令数 \\(N\\) 的事。</p><p>超标量把 \\(W\\gt 1\\) 之后，相关与端口会让 \\(u\\) 远小于 1：宽度 4 而 IPC 1.5 很常见。本课不引入发射逻辑，只把这个比值的位置留好。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 IPC 写成可以大于宽度：那是计数错误或把别的硬件线程算进来。<a href="/cs/smt">SMT</a> 才用多线程填空档。也不把 GPU 占用率写进来。Gustafson 按问题规模放大仍不在本课。</p><p>后课默认：谈到吞吐，可以用 CPI 或 IPC；五级理想 IPC = 1。存储器层次将主导实测 IPC 掉到何处。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IPC 是提交指令数除以时钟，单线程下与 CPI 互为倒数。</li><li>利用率对照理想发射宽度；宽度 1 时即 IPC 本身。</li><li>局部性与 cache 将改写停顿项，对象仍是这条吞吐定义。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em> 第 1 章与流水线性能。</li></ul>',9))])}const B=o(c,[["render",d]]);export{_ as __pageData,B as default};
